using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace Impostor.Server.LlmBots.Brain
{
    /// <summary>
    ///     Turns whatever a language model answered into a <see cref="MeetingDecision"/> that is safe to act on.
    /// </summary>
    internal static class DecisionParser
    {
        private static readonly Regex Confession = new(@"\b(i am|i'm|im|as an?|i was) (the |an? )?(impostor|imposter)\b|\bmy (impostor|imposter) (team|partner|mate)|\bwe('re| are) (both )?(the )?(impostors|imposters)", RegexOptions.IgnoreCase | RegexOptions.Compiled);

        private static readonly Regex SayKey = new("\"(?:say|lines|messages|message|chat|text)\"\\s*:\\s*", RegexOptions.IgnoreCase | RegexOptions.Compiled);

        private static readonly Regex VoteKey = new("\"(?:vote|vote_for|final_vote|target)\"\\s*:\\s*", RegexOptions.IgnoreCase | RegexOptions.Compiled);

        private static readonly Regex MetaTalk = new(@"\b(language model|as an ai|i am an ai|i'm an ai|artificial intelligence|chatgpt|openai|anthropic|system prompt|json)\b", RegexOptions.IgnoreCase | RegexOptions.Compiled);

        public static MeetingDecision? Parse(string text, MeetingContext ctx, string source)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return null;
            }

            var json = ExtractJson(text);
            List<string> say = new();
            string? vote = null;

            if (json != null)
            {
                try
                {
                    using var doc = JsonDocument.Parse(json, new JsonDocumentOptions { AllowTrailingCommas = true, CommentHandling = JsonCommentHandling.Skip });
                    var root = doc.RootElement;
                    if (root.ValueKind == JsonValueKind.Object)
                    {
                        foreach (var name in new[] { "say", "lines", "messages", "message", "chat", "text" })
                        {
                            if (TryGet(root, name, out var value))
                            {
                                say.AddRange(ReadLines(value));
                                break;
                            }
                        }

                        foreach (var name in new[] { "vote", "vote_for", "target", "final_vote" })
                        {
                            if (TryGet(root, name, out var value) && value.ValueKind == JsonValueKind.String)
                            {
                                vote = value.GetString();
                                break;
                            }
                        }
                    }
                }
                catch (JsonException)
                {
                    json = null;
                }
            }

            if (json == null)
            {
                var salvaged = Salvage(text);
                if (salvaged != null)
                {
                    say.AddRange(salvaged.Value.Say);
                    vote = salvaged.Value.Vote;
                }
                else
                {
                    // No usable JSON: treat a short plain answer as one chat line.
                    var plain = text.Trim();
                    if (plain.Length is > 0 and <= 160 && !plain.Contains('{') && !plain.Contains('['))
                    {
                        say.Add(plain);
                    }
                    else
                    {
                        return null;
                    }
                }
            }

            var cleaned = say
                .Select(l => Clean(l, ctx))
                .Where(l => l.Length > 0 && !MetaTalk.IsMatch(l) && !(ctx.IAmImpostor && Confession.IsMatch(l)))
                .Take(ctx.MaxLines)
                .ToList();

            return new MeetingDecision(cleaned, NormalizeVote(vote, ctx), source);
        }

        /// <summary>
        ///     Tells whether an answer has the shape that was asked for: a JSON object, or at least recognisable
        ///     "say" and "vote" fields. Plain prose does not count, it may come from a model that ignored the task.
        /// </summary>
        /// <param name="text">The answer.</param>
        /// <returns>True when <see cref="Parse"/> will find the fields in it.</returns>
        internal static bool LooksUsable(string text)
        {
            return !string.IsNullOrWhiteSpace(text) && (ExtractJson(text) != null || Salvage(text) != null);
        }

        /// <summary>
        ///     Pulls the chat lines and the vote out of an answer that is not valid JSON (cut off, stray quotes,
        ///     missing brackets), which small models produce now and then.
        /// </summary>
        /// <param name="text">The answer.</param>
        /// <returns>What was found, or null when there is nothing that looks like a "say" or "vote" field.</returns>
        internal static (List<string> Say, string? Vote)? Salvage(string text)
        {
            var say = new List<string>();
            string? vote = null;
            var found = false;

            var key = SayKey.Match(text);
            if (key.Success)
            {
                found = true;
                var i = key.Index + key.Length;
                if (i < text.Length && text[i] == '[')
                {
                    i++;
                    while (i < text.Length && text[i] != ']')
                    {
                        if (text[i] == '"')
                        {
                            var line = ReadString(text, ref i, out var closed);
                            if (closed && line.Length > 0)
                            {
                                say.Add(line);
                            }

                            continue;
                        }

                        i++;
                    }
                }
                else if (i < text.Length && text[i] == '"')
                {
                    var line = ReadString(text, ref i, out var closed);
                    if (closed && line.Length > 0)
                    {
                        say.Add(line);
                    }
                }
            }

            var voteMatch = VoteKey.Match(text);
            if (voteMatch.Success)
            {
                found = true;
                var i = voteMatch.Index + voteMatch.Length;
                if (i < text.Length && text[i] == '"')
                {
                    vote = ReadString(text, ref i, out _);
                }
            }

            return found ? (say, vote) : null;
        }

        // Reads a string literal starting at the opening quote. A quote only ends the string when what follows looks
        // like the end of a JSON value, so an unescaped quote inside a sentence does not cut the line short.
        private static string ReadString(string text, ref int i, out bool closed)
        {
            var sb = new StringBuilder();
            closed = false;
            for (i++; i < text.Length; i++)
            {
                var c = text[i];
                if (c == '\\' && i + 1 < text.Length)
                {
                    i++;
                    switch (text[i])
                    {
                        case 'n':
                        case 't':
                        case 'r':
                            sb.Append(' ');
                            break;
                        case 'u' when i + 4 < text.Length && int.TryParse(text.AsSpan(i + 1, 4), System.Globalization.NumberStyles.HexNumber, null, out var code):
                            sb.Append((char)code);
                            i += 4;
                            break;
                        default:
                            sb.Append(text[i]);
                            break;
                    }

                    continue;
                }

                if (c == '"')
                {
                    var next = i + 1;
                    while (next < text.Length && char.IsWhiteSpace(text[next]))
                    {
                        next++;
                    }

                    if (next >= text.Length || text[next] is ',' or ']' or '}' or ':')
                    {
                        closed = true;
                        i++;
                        return sb.ToString().Trim();
                    }
                }

                sb.Append(c);
            }

            return sb.ToString().Trim();
        }

        internal static string? ExtractJson(string text)
        {
            var start = text.IndexOf('{');
            while (start >= 0)
            {
                var depth = 0;
                var inString = false;
                var escaped = false;
                for (var i = start; i < text.Length; i++)
                {
                    var c = text[i];
                    if (inString)
                    {
                        if (escaped)
                        {
                            escaped = false;
                        }
                        else if (c == '\\')
                        {
                            escaped = true;
                        }
                        else if (c == '"')
                        {
                            inString = false;
                        }

                        continue;
                    }

                    if (c == '"')
                    {
                        inString = true;
                    }
                    else if (c == '{')
                    {
                        depth++;
                    }
                    else if (c == '}')
                    {
                        depth--;
                        if (depth == 0)
                        {
                            var candidate = text.Substring(start, i - start + 1);
                            if (candidate.Contains("\"say\"", StringComparison.Ordinal) || candidate.Contains("\"vote\"", StringComparison.Ordinal))
                            {
                                return candidate;
                            }

                            break;
                        }
                    }
                }

                start = text.IndexOf('{', start + 1);
            }

            return null;
        }

        private static bool TryGet(JsonElement root, string name, out JsonElement value)
        {
            foreach (var property in root.EnumerateObject())
            {
                if (string.Equals(property.Name, name, StringComparison.OrdinalIgnoreCase))
                {
                    value = property.Value;
                    return true;
                }
            }

            value = default;
            return false;
        }

        private static IEnumerable<string> ReadLines(JsonElement value)
        {
            if (value.ValueKind == JsonValueKind.String)
            {
                yield return value.GetString() ?? string.Empty;
            }
            else if (value.ValueKind == JsonValueKind.Array)
            {
                foreach (var item in value.EnumerateArray())
                {
                    if (item.ValueKind == JsonValueKind.String)
                    {
                        yield return item.GetString() ?? string.Empty;
                    }
                }
            }
        }

        private static string Clean(string line, MeetingContext ctx)
        {
            var text = line.Replace("\r", " ").Replace("\n", " ").Trim().Trim('"', '\'', '`');

            // Models like to prefix their own name.
            var prefix = ctx.Me.Name + ":";
            if (text.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
            {
                text = text.Substring(prefix.Length).Trim();
            }

            var builder = new StringBuilder();
            foreach (var c in text)
            {
                if (c >= ' ' && c != '\u007f')
                {
                    builder.Append(c);
                }
            }

            text = builder.ToString().Trim();
            if (text.Length > 100)
            {
                var cut = text.LastIndexOf(' ', 99);
                text = text.Substring(0, cut > 40 ? cut : 100);
            }

            return text;
        }

        private static string? NormalizeVote(string? vote, MeetingContext ctx)
        {
            if (string.IsNullOrWhiteSpace(vote))
            {
                return null;
            }

            var t = vote.Trim().Trim('"', '\'', '.', '!');
            if (t.Equals("skip", StringComparison.OrdinalIgnoreCase) || t.Equals("none", StringComparison.OrdinalIgnoreCase) || t.StartsWith("skip", StringComparison.OrdinalIgnoreCase))
            {
                return "skip";
            }

            var player = ctx.FindByName(t);
            if (player == null || player.IsMe || !player.Alive || player.IsTeammate)
            {
                return null;
            }

            return player.Name;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace Impostor.Server.LlmBots.Brain
{
    /// <summary>
    ///     Plays meetings with rules and templates. No network needed. Also the fallback when an LLM is unavailable.
    /// </summary>
    internal sealed class HeuristicBrain : IBrain
    {
        private readonly Random _rng;

        public HeuristicBrain(int seed)
        {
            _rng = new Random(seed);
        }

        public string Name => "heuristic";

        public ValueTask<MeetingDecision> DecideAsync(MeetingContext ctx, CancellationToken cancellationToken)
        {
            return new ValueTask<MeetingDecision>(Decide(ctx));
        }

        public MeetingDecision Decide(MeetingContext ctx)
        {
            lock (_rng)
            {
                return DecideLocked(ctx);
            }
        }

        private MeetingDecision DecideLocked(MeetingContext ctx)
        {
            var say = new List<string>();
            var vote = ChooseVote(ctx);

            switch (ctx.Stage)
            {
                case MeetingStage.Opening:
                    say.AddRange(Opening(ctx, vote));
                    break;
                case MeetingStage.Reply:
                    say.AddRange(Reply(ctx, vote));
                    break;
                case MeetingStage.FinalVote:
                    if (vote != null && vote != "skip" && _rng.NextDouble() < 0.6)
                    {
                        say.Add(Pick($"voting {vote}", $"I'm going {vote}", $"{vote} it is", $"vote {vote}"));
                    }
                    else if (vote == "skip" && _rng.NextDouble() < 0.5)
                    {
                        say.Add(Pick("no proof, skipping", "skip for me", "nothing solid, skip"));
                    }

                    break;
            }

            return new MeetingDecision(say.Take(ctx.MaxLines).ToList(), vote, Name);
        }

        private static string RoomOf(MeetingContext ctx, string fallback) => ctx.BodyRoom ?? fallback;

        private static string Whereabouts(MeetingContext ctx)
        {
            var rooms = ctx.MyRouteRooms.Where(r => r != "-").Distinct().ToList();
            return rooms.Count switch
            {
                0 => "tasks",
                1 => rooms[0],
                _ => $"{rooms[^2]} then {rooms[^1]}",
            };
        }

        private string Pick(params string[] options) => options[_rng.Next(options.Length)];

        private IEnumerable<string> Opening(MeetingContext ctx, string? vote)
        {
            var lines = new List<string>();
            var caught = ctx.Caught.Select(id => ctx.Players.FirstOrDefault(p => p.Id == id)).FirstOrDefault(p => p != null && p.Alive);

            if (ctx.IAmImpostor)
            {
                lines.AddRange(ImpostorOpening(ctx));
                return lines;
            }

            if (caught != null)
            {
                lines.Add($"I SAW {caught.Name} do it. vote {caught.Name}");
                return lines;
            }

            if (ctx.Reporter != null && ctx.Reporter.IsMe && ctx.Body != null)
            {
                lines.Add(Pick(
                    $"found {ctx.Body.Name} dead in {RoomOf(ctx, "here")}",
                    $"{ctx.Body.Name}'s body is in {RoomOf(ctx, "here")}, who was near?"));
            }
            else if (ctx.Reporter != null && ctx.Body == null)
            {
                lines.Add(Pick("who called this?", $"{ctx.Reporter.Name} what's the emergency?"));
            }

            var suspect = ctx.Candidates
                .Select(p => (Player: p, Score: ctx.Suspicion.GetValueOrDefault(p.Id)))
                .OrderByDescending(x => x.Score)
                .FirstOrDefault();
            if (suspect.Player != null && suspect.Score >= 2 && ctx.Body != null && lines.Count < 2)
            {
                lines.Add(Pick(
                    $"{suspect.Player.Name} was right near the body earlier",
                    $"I saw {suspect.Player.Name} close to where {ctx.Body.Name} was found",
                    $"{suspect.Player.Name} where were you just before this?"));
                return lines;
            }

            var sighting = ctx.Sightings.LastOrDefault();
            if (sighting != null && lines.Count < 2)
            {
                lines.Add(Pick($"last I saw: {sighting}", $"I saw: {sighting}"));
            }
            else if (lines.Count < 2)
            {
                lines.Add(Pick("was just doing tasks, saw nothing", "no info from me, on tasks the whole time"));
            }

            return lines;
        }

        private IEnumerable<string> ImpostorOpening(MeetingContext ctx)
        {
            var lines = new List<string>();
            var victim = ctx.Body;
            var innocents = ctx.Candidates.Where(p => !p.IsTeammate).ToList();
            var target = innocents.Count > 0 ? innocents[_rng.Next(innocents.Count)] : null;
            var where = Whereabouts(ctx);

            if (ctx.Reporter != null && ctx.Reporter.IsMe && victim != null)
            {
                lines.Add($"found {victim.Name} in {RoomOf(ctx, "here")}, no idea who");
            }
            else
            {
                lines.Add(Pick($"I was in {where}, saw nothing", "was on tasks, didn't see anything", "just wandering tasks, no info"));
            }

            if (target != null && _rng.NextDouble() < 0.6)
            {
                lines.Add(Pick($"{target.Name} where were you?", $"{target.Name} was near there earlier I think", $"anyone seen {target.Name}?"));
            }

            return lines;
        }

        private IEnumerable<string> Reply(MeetingContext ctx, string? vote)
        {
            var lines = new List<string>();
            var accuser = ctx.Chat.LastOrDefault(c => c.SenderId != ctx.Me.Id && IsAccusation(c.Text, ctx.Me.Name));
            if (accuser != null)
            {
                var room = Whereabouts(ctx);
                lines.Add(ctx.IAmImpostor
                    ? Pick($"{accuser.SenderName} that's a reach, I was in {room}", $"why me {accuser.SenderName}? I was in {room}")
                    : Pick($"not me {accuser.SenderName}, I was in {room}", $"{accuser.SenderName} I have been on tasks, check the timeline"));
                return lines;
            }

            var accused = ctx.Chat.LastOrDefault(c => c.SenderId != ctx.Me.Id);
            if (accused != null && vote != null && vote != "skip" && _rng.NextDouble() < 0.7)
            {
                lines.Add(Pick($"leaning {vote} right now", $"{vote} feels off", $"I think {vote}"));
            }
            else if (_rng.NextDouble() < 0.4)
            {
                lines.Add(Pick("anyone got anything solid?", "need more info before voting"));
            }

            return lines;
        }

        private string? ChooseVote(MeetingContext ctx)
        {
            var candidates = ctx.Candidates.ToList();
            if (candidates.Count == 0)
            {
                return "skip";
            }

            if (ctx.IAmImpostor)
            {
                // Never vote for a teammate; follow the crowd or pick the most suspicious crewmate.
                var pool = candidates.Where(p => !p.IsTeammate).ToList();
                if (pool.Count == 0)
                {
                    return "skip";
                }

                var mentioned = pool
                    .Select(p => (Player: p, Count: ctx.Chat.Count(c => c.SenderId != ctx.Me.Id && c.Text.Contains(p.Name, StringComparison.OrdinalIgnoreCase))))
                    .OrderByDescending(x => x.Count)
                    .First();
                if (mentioned.Count > 0)
                {
                    return mentioned.Player.Name;
                }

                return _rng.NextDouble() < 0.5 ? pool[_rng.Next(pool.Count)].Name : "skip";
            }

            var caught = candidates.FirstOrDefault(p => ctx.Caught.Contains(p.Id));
            if (caught != null)
            {
                return caught.Name;
            }

            var scored = candidates
                .Select(p => (Player: p, Score: ctx.Suspicion.GetValueOrDefault(p.Id) + (ctx.Chat.Count(c => c.SenderId != ctx.Me.Id && c.SenderId != p.Id && MentionsSuspiciously(c.Text, p.Name)) * 1.5)))
                .OrderByDescending(x => x.Score)
                .ToList();

            if (scored[0].Score >= 3)
            {
                return scored[0].Player.Name;
            }

            return "skip";
        }

        private static bool IsAccusation(string text, string name)
        {
            if (!text.Contains(name, StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            var t = text.ToLowerInvariant();
            return t.Contains("sus") || t.Contains("vote") || t.Contains("where were you") || t.Contains("near") || t.Contains("close to")
                   || t.Contains("vent") || t.Contains("kill") || t.Contains("acting off") || t.Contains("feels off") || t.Contains('?') || t.Contains("did it");
        }

        private static bool MentionsSuspiciously(string text, string name)
        {
            if (!text.Contains(name, StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            var t = text.ToLowerInvariant();
            return t.Contains("sus") || t.Contains("vote") || t.Contains("saw") || t.Contains("vent") || t.Contains("kill") || t.Contains("near");
        }
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;
using Impostor.Server.LlmBots.Llm;
using Microsoft.Extensions.Logging;

namespace Impostor.Server.LlmBots.Brain
{
    /// <summary>
    ///     Lets a language model play the meetings. Anything that goes wrong (no key, limits, bad answers)
    ///     falls back to <see cref="HeuristicBrain"/> so a bot never freezes.
    /// </summary>
    internal sealed class LlmBrain : IBrain
    {
        private readonly OpenRouterClient _client;
        private readonly HeuristicBrain _fallback;
        private readonly ILogger _logger;
        private readonly Action<string>? _rawLog;

        public LlmBrain(OpenRouterClient client, HeuristicBrain fallback, ILogger logger, Action<string>? rawLog = null)
        {
            _client = client;
            _fallback = fallback;
            _logger = logger;
            _rawLog = rawLog;
        }

        public string Name => "llm";

        public async ValueTask<MeetingDecision> DecideAsync(MeetingContext ctx, CancellationToken cancellationToken)
        {
            if (!_client.Available)
            {
                return _fallback.Decide(ctx) with { Source = "heuristic (llm unavailable)" };
            }

            var user = PromptBuilder.User(ctx);
            var important = ctx.Stage == MeetingStage.FinalVote;
            var maxWait = ctx.Stage switch
            {
                MeetingStage.Opening => TimeSpan.FromSeconds(6),
                MeetingStage.Reply => TimeSpan.FromSeconds(4),
                _ => TimeSpan.FromSeconds(12),
            };

            try
            {
                var reply = await _client.CompleteAsync(PromptBuilder.SystemPrompt, user, important, maxWait, cancellationToken, accept: DecisionParser.LooksUsable, preferredModel: ctx.PreferredModel);
                _rawLog?.Invoke($"=== {ctx.Me.Name} {ctx.Stage} via {reply.Model} ({reply.LatencyMs} ms)\n--- prompt\n{user}\n--- answer\n{reply.Text}\n");

                var parsed = DecisionParser.Parse(reply.Text, ctx, "llm:" + reply.Model);
                if (parsed == null)
                {
                    _logger.LogWarning("Could not understand the answer of {Model}, using heuristics for this step", reply.Model);
                    return _fallback.Decide(ctx) with { Source = "heuristic (unparsable llm answer)" };
                }

                if (ctx.Stage == MeetingStage.FinalVote && parsed.Vote == null)
                {
                    parsed = parsed with { Vote = _fallback.Decide(ctx).Vote };
                }

                return parsed;
            }
            catch (LlmUnavailableException ex)
            {
                _logger.LogDebug("LLM unavailable: {Reason}", ex.Message);
                return _fallback.Decide(ctx) with { Source = "heuristic (" + ex.Message + ")" };
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace Impostor.Server.LlmBots.Brain
{
    internal enum MeetingStage
    {
        Opening,
        Reply,
        FinalVote,
    }

    internal sealed record PlayerBrief(byte Id, string Name, string Color, bool Alive, bool IsMe, bool IsTeammate, bool IsHuman = false);

    /// <summary>
    ///     Everything a brain gets to see when it has to talk or vote in a meeting.
    /// </summary>
    internal sealed class MeetingContext
    {
        public string MapName { get; set; } = "The Skeld";

        public int MeetingNumber { get; set; }

        public MeetingStage Stage { get; set; }

        public PlayerBrief Me { get; set; } = null!;

        public bool IAmImpostor { get; set; }

        public IReadOnlyList<PlayerBrief> Players { get; set; } = Array.Empty<PlayerBrief>();

        public string Reason { get; set; } = string.Empty;

        public string? BodyRoom { get; set; }

        public PlayerBrief? Reporter { get; set; }

        public PlayerBrief? Body { get; set; }

        /// <summary>Gets or sets what the bot saw or worked out, oldest first, in plain sentences.</summary>
        public IReadOnlyList<string> Observations { get; set; } = Array.Empty<string>();

        /// <summary>Gets or sets the whereabouts timeline: who was seen where.</summary>
        public IReadOnlyList<string> Sightings { get; set; } = Array.Empty<string>();

        /// <summary>Gets or sets the things only an impostor knows (its own kills, its teammates).</summary>
        public IReadOnlyList<string> SecretFacts { get; set; } = Array.Empty<string>();

        public IReadOnlyList<string> MyTasks { get; set; } = Array.Empty<string>();

        /// <summary>Gets or sets the rooms this bot walked through recently, oldest first, with how long ago.</summary>
        public IReadOnlyList<string> MyRoute { get; set; } = Array.Empty<string>();

        /// <summary>Gets or sets the room names of <see cref="MyRoute"/> without timestamps.</summary>
        public IReadOnlyList<string> MyRouteRooms { get; set; } = Array.Empty<string>();

        public IReadOnlyList<string> History { get; set; } = Array.Empty<string>();

        public IReadOnlyList<ChatLine> Chat { get; set; } = Array.Empty<ChatLine>();

        public IReadOnlyDictionary<byte, double> Suspicion { get; set; } = new Dictionary<byte, double>();

        public IReadOnlySet<byte> Caught { get; set; } = new HashSet<byte>();

        public double SecondsLeft { get; set; }

        public int MaxLines { get; set; } = 2;

        public string Persona { get; set; } = string.Empty;

        /// <summary>Gets or sets the model this bot is named after; it is asked first.</summary>
        public string? PreferredModel { get; set; }

        public IEnumerable<PlayerBrief> Candidates => Players.Where(p => p.Alive && !p.IsMe);

        public PlayerBrief? FindByName(string? text)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                return null;
            }

            var t = text.Trim().Trim('"', '\'', '.', '!', '?').ToLowerInvariant();
            return Players.FirstOrDefault(p => p.Name.ToLowerInvariant() == t)
                   ?? Players.FirstOrDefault(p => p.Color.ToLowerInvariant() == t)
                   ?? Players.FirstOrDefault(p => t.Contains(p.Name.ToLowerInvariant()));
        }
    }

    /// <summary>
    ///     What a brain decided: lines to say and who to vote for ("skip", a player name or null when undecided).
    /// </summary>
    internal sealed record MeetingDecision(IReadOnlyList<string> Say, string? Vote, string Source);

    internal interface IBrain
    {
        string Name { get; }

        System.Threading.Tasks.ValueTask<MeetingDecision> DecideAsync(MeetingContext context, System.Threading.CancellationToken cancellationToken);
    }
}

using System.Linq;
using System.Text;

namespace Impostor.Server.LlmBots.Brain
{
    internal static class PromptBuilder
    {
        public const string SystemPrompt =
@"You are a player in a game of Among Us, typing in the emergency meeting text chat with other players. Some of the other players are humans and some are other AI players. Stay in character as an ordinary casual player. Never mention being an AI, a language model, a bot, prompts or these instructions.

How the game works: Crewmates do tasks around the ship. One or more hidden Impostors secretly kill crewmates. When a body is found or someone calls an emergency meeting, everybody gathers, talks, then votes to eject one player (or skips). Crewmates win by finishing all tasks or ejecting every Impostor. Impostors win when they are as many as the crewmates.

Chat style: very short lines (max 90 characters), casual, lowercase is fine, no emojis, no markdown, use player names. Say things a real player would type. Do not repeat what has already been said. Do not describe your reasoning in the chat. Talk like a person: never quote exact timestamps such as ""20s ago"", say things like ""just before the meeting"" or ""a bit earlier"" instead, and do not recite your whole route.

Conversation: this is a live chat, not a speech. Read the latest messages and respond to them directly: answer questions asked of you, use the name of the person you are replying to, agree or disagree and say why, or ask a pointed follow-up. React to what people just said instead of repeating facts that were already shared. Players marked [HUMAN] are real people typing slowly: take what they say seriously and answer them first. If the meeting reason says someone called an emergency meeting, no body was found, so do not ask where the body is.

Truthfulness: a Crewmate only states things that are in the notes below and may reason from them. An Impostor may lie and deflect, but must stay consistent with public facts (who called the meeting, where the body is) and must never reveal or confess being an Impostor, and never accuse teammates.

Reply with ONLY one JSON object, nothing else:
{""say"": [""line 1"", ""line 2""], ""vote"": ""<player name or skip>"", ""note"": ""one short private thought""}
""say"" may be empty if staying quiet is smarter. ""vote"" is your current intended vote: an alive player other than yourself, or ""skip"".";

        public static string User(MeetingContext ctx)
        {
            var b = new StringBuilder();
            b.AppendLine($"MAP: {ctx.MapName}. Meeting number {ctx.MeetingNumber + 0}. About {(int)ctx.SecondsLeft} seconds of this meeting are left.");
            b.AppendLine($"YOU ARE: {ctx.Me.Name} ({ctx.Me.Color}). Your role: {(ctx.IAmImpostor ? "IMPOSTOR (secret!)" : "CREWMATE")}.");

            if (ctx.Persona.Length > 0)
            {
                b.AppendLine("YOUR PERSONALITY: " + ctx.Persona);
            }

            foreach (var secret in ctx.SecretFacts)
            {
                b.AppendLine("SECRET: " + secret);
            }

            b.AppendLine();
            b.AppendLine("PLAYERS:");
            foreach (var p in ctx.Players)
            {
                b.AppendLine($"- {p.Name} ({p.Color}){(p.IsMe ? " [you]" : string.Empty)}{(p.IsHuman ? " [HUMAN]" : string.Empty)}{(p.Alive ? string.Empty : " [DEAD]")}");
            }

            b.AppendLine();
            b.AppendLine("WHY THIS MEETING: " + ctx.Reason);

            if (ctx.MyTasks.Count > 0)
            {
                b.AppendLine();
                b.AppendLine(ctx.IAmImpostor ? "YOUR (FAKE) TASK LIST, use it as your cover story:" : "YOUR TASKS:");
                foreach (var t in ctx.MyTasks)
                {
                    b.AppendLine("- " + t);
                }
            }

            if (ctx.MyRoute.Count > 0)
            {
                b.AppendLine();
                b.AppendLine(ctx.IAmImpostor ? "WHERE YOU REALLY WERE (you may lie about it):" : "WHERE YOU HAVE BEEN (oldest first):");
                b.AppendLine(string.Join(" -> ", ctx.MyRoute));
            }

            if (ctx.Observations.Count > 0)
            {
                b.AppendLine();
                b.AppendLine("WHAT YOU SAW OR FOUND OUT (oldest first):");
                foreach (var o in ctx.Observations)
                {
                    b.AppendLine("- " + o);
                }
            }

            if (ctx.Sightings.Count > 0)
            {
                b.AppendLine();
                b.AppendLine("WHERE YOU SAW OTHER PLAYERS (oldest first):");
                foreach (var s in ctx.Sightings)
                {
                    b.AppendLine("- " + s);
                }
            }
            else
            {
                b.AppendLine();
                b.AppendLine("You did not see any other player recently.");
            }

            if (ctx.History.Count > 0)
            {
                b.AppendLine();
                b.AppendLine("EARLIER MEETINGS:");
                foreach (var h in ctx.History)
                {
                    b.AppendLine("- " + h);
                }
            }

            b.AppendLine();
            if (ctx.Chat.Count > 0)
            {
                b.AppendLine("CHAT SO FAR:");
                foreach (var line in ctx.Chat.TakeLast(20))
                {
                    b.AppendLine($"{line.SenderName}: {line.Text}");
                }
            }
            else
            {
                b.AppendLine("CHAT SO FAR: (nobody has spoken yet)");
            }

            b.AppendLine();
            b.AppendLine(ctx.Stage switch
            {
                MeetingStage.Opening => $"YOUR TURN: say your opening line(s), at most {ctx.MaxLines} and keep them casual. Share one or two useful things (roughly where you were, who you saw, anything suspicious) or ask a pointed question. Set your current vote.",
                MeetingStage.Reply => "YOUR TURN: reply with ONE short line to the newest messages in the chat (address the person by name). Answer anyone who accused you or asked you something, back up or challenge a claim, or ask a follow-up. Do not repeat facts already said. Update your vote.",
                _ => "YOUR TURN: voting closes soon. You may add one last short line. Give your FINAL vote.",
            });

            b.AppendLine(ctx.IAmImpostor
                ? "Reminder: you are the Impostor. Blend in, keep your story consistent with your task list, sound natural, and steer the vote toward a crewmate without being pushy."
                : "Reminder: you are a Crewmate. Do not invent facts you have not seen. If you SAW a kill or a vent, say so plainly and vote for that player.");
            return b.ToString();
        }
    }
}

